{"witnessCode": "import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('keepQueryParameters single item', () => {
  it('should keep only the specified query parameter', () => {
    const url = 'http://example.com?foo=1&bar=2&baz=3';
    const options = {
      keepQueryParameters: ['foo'],
      removeQueryParameters: [],
      stripHash: false,
      sortQueryParameters: true,
    };
    const expected = 'http://example.com/?foo=1';
    const actual = normalizeUrl(url, options);
    assert.strictEqual(actual, expected);
  });
});"}
